<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/vue'

import AuthModal from '@@/components/auth/AuthModal.vue'
import MfaCodeForm, { type MfaCodeSubmit } from '@@/components/auth/MfaCodeForm.vue'
import { reportAuthError } from '@@/lib/auth'
import { MFA_TEXTS, mfaErrorMessage } from '@@/lib/mfa'

// Global step-up dialog: the backend answered 403 `mfa_step_up` (session without a second
// factor on a panel that requires 2FA). It cannot be dismissed without a code — the only
// alternative is logging out (auth-client resets the MFA stage on logout, so the dialog
// closes by itself). Rendered by <AuthMfaDialogs /> (after app.use(createAuth(...))).
const { stage, stepUp } = useMfa()
const { logout, isAuthenticated } = useAuth()
const error = ref<string | null>(null)

const open = computed(() => isAuthenticated.value && stage.value === 'step-up')
const pending = computed(() => stepUp.isPending.value)

async function handleSubmit(data: MfaCodeSubmit) {
  error.value = null
  try {
    await stepUp(data)
  } catch (err) {
    // Unexpected errors were already reported by the `login-error` listener (lib/auth.ts).
    error.value = mfaErrorMessage(err) ?? MFA_TEXTS.verifyFailed
  }
}

function handleLogout() {
  void logout().catch((err: unknown) => reportAuthError(err, MFA_TEXTS.logoutFailed))
}
</script>

<template>
  <AuthModal
    :open="open"
    title="Potwierdź tożsamość"
    description="Ten panel wymaga weryfikacji dwuetapowej. Wpisz kod z aplikacji uwierzytelniającej, aby kontynuować."
  >
    <MfaCodeForm
      :is-pending="pending"
      :error="error"
      submit-label="Potwierdź"
      cancel-label="Wyloguj się"
      @submit="handleSubmit"
      @cancel="handleLogout"
    />
  </AuthModal>
</template>
